#pragma once
#include "Processor.h"
#include "OscAdvanced.h"
namespace noctrl {
inline void addOscParameters(juce::AudioProcessorValueTreeState::ParameterLayout& l){using namespace juce;
 auto f=[&](String id,String title,float lo,float hi,float def){l.add(std::make_unique<AudioParameterFloat>(id,title,NormalisableRange<float>(lo,hi),def));};
 auto b=[&](String id,String title,bool def){l.add(std::make_unique<AudioParameterBool>(id,title,def));};auto c=[&](String id,String title,StringArray items,int def){l.add(std::make_unique<AudioParameterChoice>(id,title,items,def));};
 for(int o=1;o<=3;++o){String id="osc"+String(o);c(id+"loop","Sample play mode",{"Auto","One-shot","Fwd Loop","Fwd / Rev Loop","Rev Loop","Tailed"},0);c(id+"source","Oscillator type",{"Wavetable","Sample","Granular","Spectral","Multisample"},0);b(id+"enabled","Osc "+String(o)+" enabled",true);f(id+"semi","Osc semitones",-12,12,0);f(id+"fine","Osc fine cents",-100,100,0);f(id+"phase","Osc initial phase",0,360,0);f(id+"random","Osc random phase",0,1,1);f(id+"pan","Osc pan",-1,1,0);f(id+"blend","Osc unison blend",0,1,1);c(id+"routing","Osc routing",{"Filter 1","Filter 2","Both","Main","Direct","None","Bus 1","Bus 2"},0);for(int w=1;w<=2;++w){String wi=id+"warp"+String(w);c(wi+"mode","Warp mode",oscillatorWarpNames(),0);f(wi,"Warp amount",0,1,0);}}
 for(int e=1;e<=4;++e){String id="env"+String(e);if(e>2){f(id+"a","Envelope attack",.001f,5,.01f);f(id+"d","Envelope decay",.005f,5,.35f);f(id+"s","Envelope sustain",0,1,0);f(id+"r","Envelope release",.005f,8,.35f);}f(id+"hold","Envelope hold",0,3,0);}
 for(int i=1;i<=8;++i){String id="lfo"+String(i);if(i>2){f(id+"rate","LFO rate",.03f,20,1);c(id+"shape","LFO shape",{"Sine","Triangle","Saw","Square","Custom"},0);c(id+"sync","LFO sync",{"Free Hz","1/16","1/8","1/4","1/2","1 bar","2 bars"},0);}b(id+"edited","User LFO curve",false);f(id+"phase","LFO phase",0,1,0);b(id+"retrigger","LFO retrigger",false);b(id+"oneshot","LFO one shot",false);for(int k=0;k<16;++k)f(id+"point"+String(k+1),"LFO curve point",-1,1,std::sin(juce::MathConstants<float>::twoPi*k/15));}
 for(int m=3;m<=8;++m)f("macro"+String(m),"Macro "+String(m),0,1,0);
 b("subEnabled","Sub enabled",true);b("noiseEnabled","Noise enabled",true);c("subShape","Sub waveform",{"Sine","Triangle","Saw","Square","Rounded Square","Pulse 25%"},0);f("subPan","Sub pan",-1,1,0);f("subOct","Sub octave",-3,1,-1);f("noisePan","Noise pan",-1,1,0);f("noisePitch","Noise pitch",-24,24,0);
 for(int j=1;j<=2;++j){String id="filter"+String(j);f(id+"drive","Filter drive",0,1,0);f(id+"wet","Filter mix",0,1,1);f(id+"pan","Filter pan",-1,1,0);}
 b("filterSerial","Serial filters",true);b("mono","Mono voice mode",false);f("polyphony","Voice limit",1,64,12);f("glide","Glide time",0,2,0);
 for(int f=1;f<=2;++f){String id="filter"+String(f);b(id+"enabled","Filter enabled",true);c(id+"route","Filter output",{"Auto","Main","Direct","Other filter","Bus 1","Bus 2","None"},0);}
 addMixParameters(l);
}
inline void applyOscSettings(SynthProcessor& p){auto& s=p.settings;auto get=[&](juce::String id){return p.dspValue(id);};for(int i=0;i<3;++i){auto id="osc"+juce::String(i+1);auto& o=s.osc[i];o.loopMode=(int)get(id+"loop");o.sourceMode=(int)get(id+"source");o.enabled=get(id+"enabled")>.5f;o.semi=std::round(get(id+"semi"));o.fine=get(id+"fine");o.initial=get(id+"phase")/360;o.random=get(id+"random");o.pan=get(id+"pan");o.blend=get(id+"blend");o.routing=(int)get(id+"routing");for(int w=0;w<2;++w){auto k=id+"warp"+juce::String(w+1);o.warp[w]=(int)get(k+"mode");o.warpAmount[w]=get(k);}}
 applyOscAdvancedSettings(p);for(int e=0;e<4;++e){auto id="env"+juce::String(e+1);s.envelopes[e]={get(id+"a"),get(id+"d"),get(id+"s"),get(id+"r")};s.hold[e]=get(id+"hold");s.envTempoSync[e]=get(id+"sync")>.5f;if(s.envTempoSync[e]){s.envelopes[e].attack=juce::jmax(.001f,envelopeBeatSeconds((int)get(id+"aBeat"),s.bpm));s.hold[e]=envelopeBeatSeconds((int)get(id+"holdBeat"),s.bpm);s.envelopes[e].decay=juce::jmax(.001f,envelopeBeatSeconds((int)get(id+"dBeat"),s.bpm));s.envelopes[e].release=juce::jmax(.001f,envelopeBeatSeconds((int)get(id+"rBeat"),s.bpm));}}s.amp=s.envelopes[0];s.mod=s.envelopes[1];
 for(int l=0;l<8;++l){auto id="lfo"+juce::String(l+1);s.lfoRate[l]=get(id+"rate");s.lfoShape[l]=(int)get(id+"shape");s.lfoSync[l]=(int)get(id+"sync");s.lfoEdited[l]=get(id+"edited")>.5f;s.lfoOffset[l]=get(id+"phase");s.lfoRetrigger[l]=get(id+"retrigger")>.5f;s.lfoOneShot[l]=get(id+"oneshot")>.5f;for(int k=0;k<16;++k)s.lfoPoints[l][k]=get(id+"point"+juce::String(k+1));}
 for(int m=2;m<8;++m)s.macro[m]=get("macro"+juce::String(m+1));for(int f=0;f<2;++f){auto id="filter"+juce::String(f+1);s.filterEnabled[f]=get(id+"enabled")>.5f;s.filterRoute[f]=(int)get(id+"route");s.filterDrive[f]=get(id+"drive");s.filterWet[f]=get(id+"wet");s.filterPan[f]=get(id+"pan");}
 s.subEnabled=get("subEnabled")>.5f;s.noiseEnabled=get("noiseEnabled")>.5f;s.subShape=(int)get("subShape");s.subPan=get("subPan");s.subOct=std::round(get("subOct"));s.subCoarse=get("subCoarse");s.subInitial=get("subPhase")/360;s.noisePan=get("noisePan");s.noisePitch=get("noisePitch");s.serial=get("filterSerial")>.5f;s.mono=get("mono")>.5f;s.polyphony=(int)get("polyphony");s.glide=get("glide");s.legato=get("legato")>.5f;s.portaAlways=get("portaAlways")>.5f;s.portaScaled=get("portaScaled")>.5f;s.portaCurve=get("portaCurve");for(int i=0;i<16;++i){s.velocityCurve[i]=get("velocityCurve"+juce::String(i+1));s.noteCurve[i]=get("noteCurve"+juce::String(i+1));}for(int i=0;i<7;++i){auto key=i<5?mixSources[i]:"Filter"+juce::String(i-4);if(i<5)s.mix.balance[i]=get("mix"+key+"Balance");for(int b=0;b<2;++b)s.mix.send[i][b]=get("mix"+key+"Bus"+juce::String(b+1));}const juce::String channels[]={"Filter1","Filter2","Bus1","Bus2","Main","Direct"};for(int i=0;i<6;++i){s.mix.gain[i]=mixDbGain(get("mix"+channels[i]+"Db"));if(i>=2){s.mix.pan[i-2]=get("mix"+channels[i]+"Pan");s.mix.enabled[i-2]=get("mix"+channels[i]+"Enabled")>.5f;}}s.mix.extraRoute[0]=(int)get("noiseRouting");s.mix.extraRoute[1]=(int)get("subRouting");for(int b=0;b<2;++b)s.mix.busRoute[b]=(int)get("mixBus"+juce::String(b+1)+"Route");
}
inline float customLfo(const Settings& s,int index,double phase){float at=(float)(phase-std::floor(phase))*15;int k=juce::jmin(14,(int)at);return s.lfoPoints[index][k]+(at-k)*(s.lfoPoints[index][k+1]-s.lfoPoints[index][k]);}
}
